      "R3": {
        "valeur": 1,
        "passage": "Ces cartes passent le gardien, le regroupement des doublons et le juge comme celles des proposeurs."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:composition"
      },
      "R5": {
